<script lang="ts">
  import{onDestroy}from'svelte';import{open}from'@tauri-apps/plugin-dialog';import{roadmapMediaApi,type BarcodeResult}from'#lib/roadmap-media-api.ts';import Notice from'#lib/ui/Notice.svelte';import CopyButton from'#lib/ui/CopyButton.svelte';
  let path=$state(''),results=$state<BarcodeResult[]>([]),error=$state(''),busy=$state(false);let requestId=0;
  async function choose(){const id=++requestId;error='';results=[];try{const selected=await open({multiple:false,filters:[{name:'Image',extensions:['png','jpg','jpeg','webp']}]});if(id!==requestId||typeof selected!=='string')return;path=selected;busy=true;const next=await roadmapMediaApi.readBarcode(path);if(id===requestId)results=next;}catch(cause){if(id===requestId)error=String(cause);}finally{if(id===requestId)busy=false;}}
  onDestroy(()=>{requestId++;});
</script>
<div class="tool" aria-busy={busy}><Notice kind="info">Reads up to 100 QR and common one-dimensional barcodes from a local PNG, JPEG or WebP image. Images are limited to 40 million pixels and each payload to 32 KiB. Codes are shown as text; links are never opened automatically.</Notice><button class="btn btn-primary" onclick={choose} disabled={busy}>{busy?'Reading image…':'Choose barcode image'}</button>{#if path}<p class="path">{path}</p>{/if}{#if !path}<Notice kind="info">Choose a clear image containing a code.</Notice>{/if}{#each results as result,index}<article class="card result"><strong>{result.format} · {index+1}</strong><p>{result.text}</p><CopyButton text={result.text}/></article>{/each}{#if error}<Notice kind="error">{error}</Notice>{/if}</div>
<style>.tool{display:grid;gap:var(--s-4)}.btn{justify-self:start}.path{overflow-wrap:anywhere;color:var(--text-2)}.result{display:grid;gap:var(--s-3);padding:var(--s-4);white-space:pre-wrap;overflow-wrap:anywhere}</style>
